const round = (clues, hint, direct, close, related, bonus = "") => ({
  clues: clues.split("|"),
  hint,
  bonuses: bonus.split("|").filter(Boolean),
  tiers: [direct, close, related].map(([reason, answers]) => ({ reason, answers: split(answers) })),
});

